// @ts-check
import { defineConfig } from "astro/config";
import mdx from "@astrojs/mdx";

import cloudflare from "@astrojs/cloudflare";

// https://astro.build/config
export default defineConfig({
	// Placeholder until the final production domain is set up (matches the
	// fallback already hardcoded in AppLayout.astro) — required so
	// rss.xml.js and canonical/OG URLs have a `site` to build against;
	// swap this for the real domain once it's live.
	site: "https://doodleai.art",
	// No @astrojs/sitemap: the sitemap is generated by src/pages/sitemap.xml.ts so
	// we control exactly which URLs are listed (it must exclude the noindex
	// /admin and /bid routes) and what lastmod reports.
	integrations: [mdx()],
	adapter: cloudflare({
		platformProxy: {
			enabled: true,
		},
	}),
	vite: {
		build: {
			rollupOptions: {
				external: [
					"@ast-grep/napi",
					"execa",
					"cross-spawn",
					"human-signals",
					"which",
					"isexe",
					"yoctocolors",
					"is-unicode-supported",
					"npm-run-path",
					"unicorn-magic",
					"path-key",
					"signal-exit",
					"get-stream",
					"strip-final-newline",
					"mimic-fn",
				],
			},
		},
		ssr: {
			// @mastra/core's optional workspace-skills feature statically pulls
			// in a chunk of Node-only CLI process-spawning tooling (execa and
			// its dependency chain) plus a native ast-grep binary — none of
			// which is installed, needed, or runnable on Cloudflare Workers.
			// /api/agent only ever calls agent.generate(), which never
			// exercises that code path, so it's safe to leave these external
			// rather than have Rollup fail trying to bundle them. See
			// README.md's Cloudflare/Mastra note.
			external: [
				"@ast-grep/napi",
				"execa",
				"cross-spawn",
				"human-signals",
				"which",
				"isexe",
				"yoctocolors",
				"is-unicode-supported",
				"npm-run-path",
				"unicorn-magic",
				"path-key",
				"signal-exit",
				"get-stream",
				"strip-final-newline",
				"mimic-fn",
			],
		},
	},
});
